import React from 'react';

export interface BrandIconProps {
  name: string;
  className?: string;
  size?: number;
}

export const hasBrandIcon = (name: string): boolean => {
  const iconKey = name.toLowerCase().replace(/[^a-z0-9]/g, '');
  const supported = [
    'figma',
    'webflow',
    'wordpress',
    'wp',
    'elementor',
    'react',
    'reactjs',
    'typescript',
    'ts',
    'javascript',
    'js',
    'tailwind',
    'tailwindcss',
    'html',
    'html5',
    'css',
    'css3',
    'scss',
    'sass',
    'photoshop',
    'ps',
    'adobephotoshop',
    'canva',
    'gsap',
    'greensock',
    'framer',
    'framermotion',
    'github',
    'git',
    'uichemy',
  ];
  return supported.includes(iconKey);
};

